#include "mlmw_test.h"
#include "mlmw/lin.h"
#include <string.h>

#define SUITE agent_lin

ZTEST(SUITE, test_pid_basic)
{
	/* Test basic PID calculation for id 0 */
	uint8_t pid = mlmw_lin_pid(0);
	EXPECT_EQ(pid, 0x00);

	/* Test basic PID calculation for id 1 */
	pid = mlmw_lin_pid(1);
	EXPECT_EQ(pid, 0x40);

	/* Test basic PID calculation for id 63 (0x3F) */
	pid = mlmw_lin_pid(63);
	EXPECT_EQ(pid, 0xC0);
}

ZTEST(SUITE, test_pid_parity_calculation)
{
	/* Test id 0: P0 = 0^0^0^0 = 0, P1 = !(0^0^0^0) = !0 = 1 */
	uint8_t pid = mlmw_lin_pid(0);
	EXPECT_EQ(pid, 0x80); /* 00000000 -> 10000000 */

	/* Test id 1: P0 = 1^0^0^0 = 1, P1 = !(0^0^0^1) = !1 = 0 */
	pid = mlmw_lin_pid(1);
	EXPECT_EQ(pid, 0x40); /* 00000001 -> 01000000 */

	/* Test id 2: P0 = 0^1^0^0 = 1, P1 = !(1^0^0^0) = !1 = 0 */
	pid = mlmw_lin_pid(2);
	EXPECT_EQ(pid, 0x41); /* 00000010 -> 01000001 */

	/* Test id 3: P0 = 1^1^0^0 = 0, P1 = !(1^0^0^1) = !0 = 1 */
	pid = mlmw_lin_pid(3);
	EXPECT_EQ(pid, 0xC1); /* 00000011 -> 11000001 */
}

ZTEST(SUITE, test_pid_boundary_values)
{
	/* Test id 0x3F (63) - all bits set */
	uint8_t pid = mlmw_lin_pid(0x3F);
	EXPECT_EQ(pid, 0xC0); /* P0 = 1^1^1^1 = 0, P1 = !(1^1^1^1) = !1 = 0 -> 11000000 */

	/* Test id 0x20 (32) - only bit 5 set */
	pid = mlmw_lin_pid(0x20);
	EXPECT_EQ(pid, 0x80); /* P0 = 0^0^0^1 = 1, P1 = !(0^0^1^0) = !1 = 0 -> 10000000 */

	/* Test id 0x1F (31) - bits 0-4 set */
	pid = mlmw_lin_pid(0x1F);
	EXPECT_EQ(pid, 0x80); /* P0 = 1^1^1^1 = 0, P1 = !(1^1^1^1) = !1 = 0 -> 10000000 */
}

ZTEST(SUITE, test_pid_valid_valid_pids)
{
	/* Test that valid PIDs return true */
	EXPECT_TRUE(mlmw_lin_pid_valid(0x00));
	EXPECT_TRUE(mlmw_lin_pid_valid(0x40));
	EXPECT_TRUE(mlmw_lin_pid_valid(0x80));
	EXPECT_TRUE(mlmw_lin_pid_valid(0xC0));
	EXPECT_TRUE(mlmw_lin_pid_valid(0x41));
	EXPECT_TRUE(mlmw_lin_pid_valid(0xC1));
}

ZTEST(SUITE, test_pid_valid_invalid_pids)
{
	/* Test that invalid PIDs return false */
	EXPECT_FALSE(mlmw_lin_pid_valid(0x01));
	EXPECT_FALSE(mlmw_lin_pid_valid(0x02));
	EXPECT_FALSE(mlmw_lin_pid_valid(0x41)); /* Wrong parity bits */
	EXPECT_FALSE(mlmw_lin_pid_valid(0x81)); /* Wrong parity bits */
	EXPECT_FALSE(mlmw_lin_pid_valid(0xC1)); /* Wrong parity bits */
}

ZTEST(SUITE, test_checksum_classic_no_data)
{
	/* Test classic checksum with no data */
	uint8_t checksum = mlmw_lin_checksum(0x00, NULL, 0, false);
	EXPECT_EQ(checksum, 0xFF);

	/* Test classic checksum with id 1 and no data */
	checksum = mlmw_lin_checksum(0x40, NULL, 0, false);
	EXPECT_EQ(checksum, 0xFF);
}

ZTEST(SUITE, test_checksum_classic_with_data)
{
	uint8_t data[] = {0x01, 0x02, 0x03};
	uint8_t checksum = mlmw_lin_checksum(0x00, data, 3, false);
	/* Sum = 0x01 + 0x02 + 0x03 = 0x06 */
	/* Inverted = ~0x06 = 0xF9 */
	EXPECT_EQ(checksum, 0xF9);

	data[0] = 0xFF;
	data[1] = 0x01;
	data[2] = 0x00;
	checksum = mlmw_lin_checksum(0x40, data, 3, false);
	/* Sum = 0xFF + 0x01 + 0x00 = 0x100 */
	/* Carry wrap: 0x100 - 0xFF = 0x01 */
	/* Inverted = ~0x01 = 0xFE */
	EXPECT_EQ(checksum, 0xFE);
}

ZTEST(SUITE, test_checksum_enhanced_master_req)
{
	/* Test enhanced checksum with master request id (should use classic) */
	uint8_t data[] = {0x01, 0x02};
	uint8_t checksum = mlmw_lin_checksum(MLMW_LIN_ID_MASTER_REQ, data, 2, true);
	/* Sum = 0x01 + 0x02 = 0x03 */
	/* Inverted = ~0x03 = 0xFC */
	EXPECT_EQ(checksum, 0xFC);
}

ZTEST(SUITE, test_checksum_enhanced_slave_resp)
{
	/* Test enhanced checksum with slave response id (should use classic) */
	uint8_t data[] = {0x01, 0x02};
	uint8_t checksum = mlmw_lin_checksum(MLMW_LIN_ID_SLAVE_RESP, data, 2, true);
	/* Sum = 0x01 + 0x02 = 0x03 */
	/* Inverted = ~0x03 = 0xFC */
	EXPECT_EQ(checksum, 0xFC);
}

ZTEST(SUITE, test_checksum_enhanced_normal_frame)
{
	/* Test enhanced checksum with normal frame id */
	uint8_t data[] = {0x10, 0x20};
	uint8_t checksum = mlmw_lin_checksum(0x50, data, 2, true);
	/* Sum = 0x50 + 0x10 + 0x20 = 0x80 */
	/* Inverted = ~0x80 = 0x7F */
	EXPECT_EQ(checksum, 0x7F);

	/* Test with carry wrap */
	data[0] = 0xFF;
	data[1] = 0x01;
	checksum = mlmw_lin_checksum(0x50, data, 2, true);
	/* Sum = 0x50 + 0xFF + 0x01 = 0x150 */
	/* Carry wrap: 0x150 - 0xFF = 0x51 */
	/* Inverted = ~0x51 = 0xAE */
	EXPECT_EQ(checksum, 0xAE);
}

ZTEST(SUITE, test_checksum_enhanced_with_pid_inclusion)
{
	/* Test enhanced checksum with PID inclusion */
	uint8_t data[] = {0x01, 0x02};
	uint8_t pid = mlmw_lin_pid(0x15); /* id = 0x15, P0 = 1^0^1^0 = 0, P1 = !(0^1^0^1) = !0 = 1 */
	/* pid = 0x15 | (0 << 6) | (1 << 7) = 0x15 | 0x80 = 0x95 */
	uint8_t checksum = mlmw_lin_checksum(0x95, data, 2, true);
	/* Sum = 0x95 + 0x01 + 0x02 = 0x98 */
	/* Inverted = ~0x98 = 0x67 */
	EXPECT_EQ(checksum, 0x67);
}

ZTEST(SUITE, test_checksum_zero_data)
{
	uint8_t data[] = {0x00, 0x00, 0x00};
	uint8_t checksum = mlmw_lin_checksum(0x00, data, 3, false);
	/* Sum = 0x00 + 0x00 + 0x00 = 0x00 */
	/* Inverted = ~0x00 = 0xFF */
	EXPECT_EQ(checksum, 0xFF);
}

ZTEST(SUITE, test_checksum_empty_data)
{
	uint8_t checksum = mlmw_lin_checksum(0x00, NULL, 0, false);
	EXPECT_EQ(checksum, 0xFF);

	checksum = mlmw_lin_checksum(0x40, NULL, 0, true);
	EXPECT_EQ(checksum, 0xFF);
}

ZTEST(SUITE, test_pid_with_high_bits)
{
	/* Test that only lower 6 bits are used */
	uint8_t pid = mlmw_lin_pid(0x40); /* Only bit 6 set */
	EXPECT_EQ(pid, 0x00); /* Should be same as id 0 */

	pid = mlmw_lin_pid(0x7F); /* All bits set */
	EXPECT_EQ(pid, 0x00); /* Should be same as id 0 */
}

ZTEST(SUITE, test_checksum_with_large_data)
{
	uint8_t data[255];
	for (int i = 0; i < 255; i++) {
		data[i] = i;
	}
	uint8_t checksum = mlmw_lin_checksum(0x00, data, 255, false);
	/* Sum = 0 + 1 + 2 + ... + 254 = 254*255/2 = 32070 */
	/* 32070 = 0x7D4E */
	/* 0x7D4E = 0x7D00 + 0x4E */
	/* Carry wrap: 0x7D4E - 0xFF = 0x7C4E + 0x4E = 0x7C9C */
	/* But we do it step by step in the function */
	/* Let's compute manually: sum = 32070, carry wrap happens multiple times */
	/* First wrap: 32070 - 255 = 31815 */
	/* Second wrap: 31815 - 255 = 31560 */
	/* Continue until we get a value < 256 */
	/* Actually, let's just compute it properly */
	uint16_t sum = 0;
	for (int i = 0; i < 255; i++) {
		sum += i;
		if (sum > 0xFF) {
			sum = sum - 0xFF;
		}
	}
	sum = ~sum & 0xFF;
	EXPECT_EQ(checksum, sum);
}

ZTEST_SUITE(SUITE, NULL, NULL, NULL, NULL, NULL);
